// #3652: `verified` means "the stored graph supports this claim". A fact that
// only ever reached the graph through `learn` was asserted by whoever taught
// it, not checked against anything -- so `learn: the earth is flat` followed
// by `verify` came back verified at 0.90 with nothing to say it was only
// taught. The status vocabulary is closed (verified/contradicted/unknown)
// across the public contract, so the distinction travels as an additive
// `grounding` field instead of a new status: `taught_only` when every
// supporting edge came from learn, `stored_graph` otherwise. A verdict with
// no supporting edge (numeric comparison) carries no grounding.
const TAUGHT_EDGE_SOURCES = new Set(['learn', 'alt']);

function supportingEdges(graph, context, workspaceId) {
  if (context.directEdge) return [context.directEdge];
  if (context.fuzzyEdge) return [context.fuzzyEdge];
  const path = context.pathSearch && Array.isArray(context.pathSearch.path) ? context.pathSearch.path : [];
  const edges = [];
  for (let i = 0; i < path.length - 1; i += 1) {
    const edge = graph.getEdges(path[i], workspaceId).find((e) => e.to === path[i + 1])
      || graph.getInEdges(path[i], workspaceId).find((e) => e.from === path[i + 1]);
    if (edge) edges.push(edge);
  }
  return edges;
}

function withGrounding(graph, data, context, workspaceId) {
  if (!data || data.status !== 'verified') return data;
  const edges = supportingEdges(graph, context, workspaceId);
  if (edges.length === 0) return data;
  const taughtOnly = edges.every((edge) => TAUGHT_EDGE_SOURCES.has(edge.source));
  return { ...data, grounding: taughtOnly ? 'taught_only' : 'stored_graph' };
}
